begin;
set local search_path=public,extensions;
select plan(34);

select ok((select count(*)=12 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['client_sites','client_site_versions','client_projects','client_project_versions','client_project_tasks','client_project_task_versions','client_annual_budgets','client_annual_budget_versions','client_cost_centers','client_cost_center_versions','client_cost_allocations','client_calendar_events'])),'twelve client portfolio records exist');
select ok((select count(*)=12 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['client_sites','client_site_versions','client_projects','client_project_versions','client_project_tasks','client_project_task_versions','client_annual_budgets','client_annual_budget_versions','client_cost_centers','client_cost_center_versions','client_cost_allocations','client_calendar_events'])),'RLS is enabled on all portfolio tables');
select ok((select count(*)=12 from pg_policies where schemaname='public'and tablename=any(array['client_sites','client_site_versions','client_projects','client_project_versions','client_project_tasks','client_project_task_versions','client_annual_budgets','client_annual_budget_versions','client_cost_centers','client_cost_center_versions','client_cost_allocations','client_calendar_events'])),'every portfolio table has an explicit read policy');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name like'client_%'and data_type in('real','double precision')),'portfolio data contains no floating point column');
select ok((select count(*)=3 and bool_and(data_type='bigint')from information_schema.columns where table_schema='public'and table_name in('client_annual_budget_versions','client_cost_allocations')and column_name in('amount_minor','approved_amount_minor')),'all budget and allocation amounts use bigint');
select ok((select data_type='integer'from information_schema.columns where table_schema='public'and table_name='client_projects'and column_name='progress_basis_points'),'project progress uses exact integer basis points');
select ok((select count(*)=6 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['client_site_versions','client_project_versions','client_project_task_versions','client_annual_budget_versions','client_cost_center_versions','client_cost_allocations'])and t.tgname like'%_immutable'and not t.tgisinternal),'versions and cost allocations are immutable');
select ok((select count(*)=8 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_client_site','create_client_project','save_client_project_version','save_client_annual_budget','create_client_cost_center','record_client_cost_allocation','save_client_project_task','schedule_client_calendar_event'])),'eight hardened server commands exist');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_client_site','create_client_project','save_client_project_version','save_client_annual_budget','create_client_cost_center','record_client_cost_allocation','save_client_project_task','schedule_client_calendar_event'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anon and service roles cannot invoke client commands');
select ok((select count(*)=8 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_client_site','create_client_project','save_client_project_version','save_client_annual_budget','create_client_cost_center','record_client_cost_allocation','save_client_project_task','schedule_client_calendar_event'])),'authenticated receives explicit command execution');
select ok(not has_table_privilege('authenticated','public.client_projects','INSERT')and not has_table_privilege('authenticated','public.client_annual_budget_versions','UPDATE')and not has_table_privilege('authenticated','public.client_cost_allocations','DELETE'),'direct client portfolio mutation is denied');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_OWNER%'and pg_get_functiondef(p.oid)like'%CLIENT_ADMIN%'and pg_get_functiondef(p.oid)like'%CLIENT_BUYER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='client_portfolio_manage'),'portfolio management is role restricted');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_ACCOUNTING%'and pg_get_functiondef(p.oid)like'%FINANCE_MANAGER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='client_budget_manage'),'budget management is finance restricted');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_VIEWER%'and pg_get_functiondef(p.oid)like'%READ_ONLY_AUDITOR%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='client_portfolio_read'),'tenant reader includes controlled client roles');
select ok((select pg_get_functiondef(p.oid)like'%organization_id=p_organization_id%'and pg_get_functiondef(p.oid)like'%status=''ACTIVE''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_client_project'),'project site is validated inside the same tenant');
select ok((select pg_get_functiondef(p.oid)like'%for update%'and pg_get_functiondef(p.oid)like'%STALE_CLIENT_PROJECT%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='save_client_project_version'),'project revisions use locking and optimistic concurrency');
select ok((select count(*)=1 from pg_constraint where conrelid='public.client_projects'::regclass and contype='u'and pg_get_constraintdef(oid)like'%organization_id, project_code%'),'project code uniqueness is tenant scoped');
select ok((select count(*)>=3 from pg_constraint where conrelid='public.client_annual_budgets'::regclass and contype='f'),'budget dimensions are referentially constrained');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and tablename='client_annual_budgets'and indexdef like'%NULLS NOT DISTINCT%'),'annual budget dimensions have null-safe uniqueness');
select ok((select pg_get_functiondef(p.oid)like'%num_nonnulls(p_library_id,p_site_id,p_project_id)<1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='save_client_annual_budget'),'annual budgets require a library site or project dimension');
select ok((select pg_get_functiondef(p.oid)like'%amount_minor%'and pg_get_functiondef(p.oid)like'%approved_amount_minor%'and pg_get_functiondef(p.oid)not like'%double precision%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='save_client_annual_budget'),'annual budgets remain exact and versioned');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_BUDGET_EXCEEDED%'and pg_get_functiondef(p.oid)like'%for update%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_client_cost_allocation'),'allocation locks and prevents budget overrun');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_ALLOCATION_RELEASE_EXCEEDED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_client_cost_allocation'),'allocation releases cannot exceed allocated value');
select ok((select count(*)>=5 from pg_constraint where conrelid='public.client_cost_allocations'::regclass and contype='f'),'cost allocations are bound to tenant budget version centre and project');
select ok((select pg_get_functiondef(p.oid)like'%count(*)filter(where status=''ACCEPTED'')*10000%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='save_client_project_task'),'task completion computes consolidated project progress');
select ok((select pg_get_functiondef(p.oid)like'%STALE_CLIENT_PROJECT_TASK%'and pg_get_functiondef(p.oid)like'%for update%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='save_client_project_task'),'task changes are concurrency safe and versioned');
select ok((select reloptions@>array['security_invoker=true']from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname='client_central_calendar'),'central calendar view honors caller RLS');
select ok((select pg_get_viewdef('public.client_central_calendar'::regclass,true)like'%mission_milestones%'and pg_get_viewdef('public.client_central_calendar'::regclass,true)like'%client_project_tasks%'),'central calendar consolidates client tasks and mission milestones');
select ok((select pg_get_functiondef(p.oid)like'%source_type%'and pg_get_functiondef(p.oid)like'%source_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_client_calendar_event'),'calendar events retain source traceability');
select ok((select count(*)=8 and bool_and(pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_client_site','create_client_project','save_client_project_version','save_client_annual_budget','create_client_cost_center','record_client_cost_allocation','save_client_project_task','schedule_client_calendar_event'])),'every command is canonically idempotent');
select ok((select count(*)=8 and bool_and(pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_client_site','create_client_project','save_client_project_version','save_client_annual_budget','create_client_cost_center','record_client_cost_allocation','save_client_project_task','schedule_client_calendar_event'])),'every command emits audit and Outbox evidence');
select ok((select count(*)=6 from pg_indexes where schemaname='public'and indexname=any(array['client_projects_status_idx','client_project_tasks_due_idx','client_budgets_year_idx','client_cost_allocations_budget_idx','client_cost_allocations_project_idx','client_calendar_timeline_idx'])),'six operational indexes support portfolio queries');
select ok((select count(*)>=4 from pg_constraint where conrelid='public.client_project_versions'::regclass and contype in('f','u','c')),'project versions are constrained and immutable snapshots');
select ok((select count(*)>=3 from pg_constraint where conrelid='public.client_calendar_events'::regclass and contype in('f','u','c')),'calendar events enforce tenant source and time consistency');

select * from finish();
rollback;
